"""Machine-authored universal gap certificates, generated by exact arithmetic.
The generator is untrusted: Lean checks every polynomial identity and bound.
"""
from generate_ead8a96f import *
def ge0(p):return all(c>=0 for c in p.values())
def lt0(p):return ge0(-p-1)
def fall_piece(d):
 if ge0(d+3):return cubic(d+3),'poly'
 if lt0(d):return sp.poly(0),'zero'
 raise ValueError(('nonuniform branch',lean(d)))
def ceval(hs,qq,jj):
 return sum((c.subst([0,0,0,qq,0,0])*fall_piece(jj-i*qq-k)[0]
   for i,h in enumerate(hs) for k,c in terms(h)),sp.poly(0))
def rewrites(hs,qq,jj,qstr,jstr):
 out=[]
 for i,h in enumerate(hs):
  for k,c in terms(h):
   _,kind=fall_piece(jj-i*qq-k)
   out.append(f' rw [vFall_{kind}M758 (({jstr})-{i}*({qstr})) {k} (by omega)]')
 return '\n'.join(out)+'\n'
def main():
 x,y=a,r
 specs=[]
 for j in range(1,5):specs.append((f'first{j}',x+8,sp.poly(j),'x+8',str(j)))
 specs.append(('low',x+y+5,x+5,'x+y+5','x+5'))
 for j in range(1,6):specs.append((f'cross{j}',x+8,x+8+j,'x+8',f'x+8+{j}'))
 specs.append(('mid',x+y+6,2*x+y+12,'x+y+6','2*x+y+12'))
 for j in range(1,4):specs.append((f'tail{j}',x+8,2*(x+8)+j,'x+8',f'2*(x+8)+{j}'))
 report=[]
 for aa,rr in cases:
  name=nm(aa,rr);hs=blocks(aa,rr)
  defs=','.join(f'{name}c{i}_{k}MEA' for i,h in enumerate(hs) for k,c in terms(h))
  src='import MarkovSmallBlocksMEA\n/-! Machine-authored ead8a96f. All-index raw small-column gap certificates. -/\n'+header
  src+=f'''\ntheorem {name}zeroMEA (q j : ℤ) (hq : 2 ≤ q) (hj : j ≤ 0) :
 {name}EMEA q j=0 := by
 unfold {name}EMEA
'''
  for i,h in enumerate(hs):
   for k,c in terms(h):src+=f' rw [vFall_zeroM758 (j-{i}*q) {k} (by omega)]\n'
  src+=' ring\n'
  src+=f'''\ntheorem {name}pastMEA (q j : ℤ) (hq : 2 ≤ q) (hj : 2*q+5 ≤ j) :
 {name}EMEA q j=0 := by
 unfold {name}EMEA
'''
  for i,h in enumerate(hs):
   for k,c in terms(h):src+=f' rw [vFall_polyM758 (j-{i}*q) {k} (by omega)]\n'
  src+=f' simp only [{defs}]\n ring\n'
  for tag,qq,jj,qstr,jstr in specs:
   gap=ceval(hs,qq,jj)**2-ceval(hs,qq,jj-1)*ceval(hs,qq,jj+1)
   neg=[(e,str(c)) for e,c in gap.items() if c<0]
   report.append(dict(a=aa,r=rr,chamber=tag,terms=len(gap),negative=neg))
   if neg:print('NEGATIVE',aa,rr,tag,neg[:5]);continue
   src+=f'''\ntheorem {name}{tag}MEA (x y : ℤ) (hx : 0 ≤ x) (hy : 0 ≤ y) :
 {name}EMEA ({qstr}) (({jstr})-1)*{name}EMEA ({qstr}) (({jstr})+1) ≤
 {name}EMEA ({qstr}) ({jstr})^2 := by
 unfold {name}EMEA
'''
   for z in [-1,1,0]:
    src+=rewrites(hs,qq,jj+z,qstr,f'({jstr})-1' if z==-1 else f'({jstr})+1' if z==1 else jstr)
   src+=f' apply sub_nonneg.mp\n simp only [{defs}]\n ring_nf\n positivity\n'
  src+=f'''
theorem {name}adjacentMEA (q j : ℤ) (hq : 2 ≤ q) :
 {name}EMEA q (j-1)*{name}EMEA q (j+1) ≤ {name}EMEA q j^2 := by
 by_cases h0 : j ≤ 1
 · rw [{name}zeroMEA q (j-1) hq (by omega),zero_mul]; exact sq_nonneg _
 by_cases h1 : 2*q+4 ≤ j
 · rw [{name}pastMEA q (j+1) hq (by omega),mul_zero]; exact sq_nonneg _
 by_cases hq8 : q < 8
 · interval_cases q <;> interval_cases j <;>
     norm_num [{name}EMEA,{defs},vFallM758]
 have hq' : 8 ≤ q := by omega
'''
  for j in range(2,5):
   src+=f''' by_cases hj{j} : j={j}
 · subst j
   convert {name}first{j}MEA (q-8) 0 (by omega) (by omega) using 1 <;> congr 1 <;> omega
'''
  src+=f''' by_cases hl : j ≤ q
 · convert {name}lowMEA (j-5) (q-j) (by omega) (by omega) using 1 <;> congr 1 <;> omega
'''
  for j in range(1,6):
   src+=f''' by_cases hc{j} : j=q+{j}
 · convert {name}cross{j}MEA (q-8) 0 (by omega) (by omega) using 1 <;> congr 1 <;> omega
'''
  src+=f''' by_cases hm : j ≤ 2*q
 · convert {name}midMEA (j-q-6) (2*q-j) (by omega) (by omega) using 1 <;> congr 1 <;> omega
 have ht : j=2*q+1 ∨ j=2*q+2 ∨ j=2*q+3 := by omega
 rcases ht with ht|ht|ht
'''
  for j in range(1,4):src+=f' · convert {name}tail{j}MEA (q-8) 0 (by omega) (by omega) using 1 <;> congr 1 <;> omega\n'
  src=src.replace('using 1 <;> congr 1 <;> omega','using 1 <;> congr 1 <;> congr 1 <;> omega')
  src+='\nend\nend MathGKM.Markov\n'
  (R/f'research/MarkovSmallLC{aa}{rr}MEA.lean').write_text(src)
 (O/'symbolic-gaps.json').write_text(json.dumps(report,indent=2)+'\n')
 print('Generated five all-index inequality modules; negative charts:',sum(bool(d['negative']) for d in report))
if __name__=='__main__':main()
